// Decides whether the assistant may send one WhatsApp message to a patient,
// before the Cloud API call is made. Pure function: no I/O, no stored history.

const WINDOW_MS = 24 * 60 * 60 * 1000;
// Meta's clock and ours can differ slightly. Inbound timestamps a little ahead
// of our clock are treated as "just now"; anything further ahead means the
// value is in the wrong unit or malformed.
const CLOCK_SKEW_MS = 5 * 60 * 1000;

/**
 * @param {{ type: "text" | "template", contact: { optedIn: boolean, lastInboundTimestamp: string | null } }} message
 * @param {Date} now server clock
 * @returns {{ allowed: boolean, reason: string | null }}
 */
export function decideWhatsApp(message, now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError("now must be a valid Date");
  }

  const type = message?.type;
  if (type !== "text" && type !== "template") {
    return deny("unsupported_message_type");
  }

  // Opt-in applies to every business-initiated message, template or not.
  // Only an explicit true counts as consent.
  if (message.contact?.optedIn !== true) {
    return deny("not_opted_in");
  }

  // Approved templates may be sent at any time to an opted-in contact,
  // including when the contact has never written to us.
  if (type === "template") {
    return allow();
  }

  // Free-form text is only allowed inside the 24-hour customer service window,
  // which opens with the patient's most recent inbound message.
  const raw = message.contact.lastInboundTimestamp;
  if (raw === null || raw === undefined) {
    return deny("no_prior_inbound_message");
  }

  // Meta sends the webhook timestamp as Unix time in whole seconds, as a string.
  const seconds = typeof raw === "string" ? raw : String(raw);
  if (!/^\d+$/.test(seconds)) {
    return deny("invalid_inbound_timestamp");
  }
  const inboundMs = Number(seconds) * 1000;
  const nowMs = now.getTime();

  if (inboundMs > nowMs + CLOCK_SKEW_MS) {
    return deny("invalid_inbound_timestamp");
  }

  // The window is open for less than 24 hours after the inbound message.
  // Exactly 24 hours is treated as closed.
  if (nowMs - inboundMs >= WINDOW_MS) {
    return deny("customer_service_window_closed");
  }

  return allow();
}

function allow() {
  return { allowed: true, reason: null };
}

function deny(reason) {
  return { allowed: false, reason };
}

import assert from "node:assert/strict";
import { decideWhatsApp } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g5-1/bot.mjs";

// 1767272400 = 2026-01-01T11:00:00Z
const TS = "1767272400";
const at = (s) => new Date(Number(s) * 1000);
const H = 3600 * 1000;
const base = (type, contact) => ({ type, contact });
const open = (extraSec) => ({ optedIn: true, lastInboundTimestamp: TS });
const nowAfter = (hours) => new Date(Date.parse("2026-01-01T11:00:00Z") + hours * H);

const cases = [
  // [name, message, now, expected]
  ["text inside window (1h)", base("text", open()), nowAfter(1), { allowed: true, reason: null }],
  ["text 23h59m59s after inbound", base("text", open()), new Date(Date.parse("2026-01-01T11:00:00Z") + 86399_000), { allowed: true, reason: null }],
  ["text exactly 24h after inbound", base("text", open()), nowAfter(24), { allowed: false, reason: "customer_service_window_closed" }],
  ["text 3 days after inbound", base("text", open()), nowAfter(72), { allowed: false, reason: "customer_service_window_closed" }],
  ["text, never inbound", base("text", { optedIn: true, lastInboundTimestamp: null }), nowAfter(1), { allowed: false, reason: "no_prior_inbound_message" }],
  ["text, inbound missing key", base("text", { optedIn: true }), nowAfter(1), { allowed: false, reason: "no_prior_inbound_message" }],
  ["text, not opted in, inside window", base("text", { optedIn: false, lastInboundTimestamp: TS }), nowAfter(1), { allowed: false, reason: "not_opted_in" }],
  ["text, optedIn is truthy string", base("text", { optedIn: "yes", lastInboundTimestamp: TS }), nowAfter(1), { allowed: false, reason: "not_opted_in" }],
  ["text, ms timestamp (13 digits) rejected", base("text", { optedIn: true, lastInboundTimestamp: "1767272400000" }), nowAfter(1), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["text, non-numeric timestamp", base("text", { optedIn: true, lastInboundTimestamp: "yesterday" }), nowAfter(1), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["text, timestamp 1 hour in future", base("text", { optedIn: true, lastInboundTimestamp: String(Number(TS) + 3600) }), nowAfter(0), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["text, timestamp 2 min ahead (skew) allowed", base("text", { optedIn: true, lastInboundTimestamp: String(Number(TS) + 120) }), nowAfter(0), { allowed: true, reason: null }],
  ["template, opted in, inside window", base("template", open()), nowAfter(1), { allowed: true, reason: null }],
  ["template, opted in, window closed", base("template", open()), nowAfter(200), { allowed: true, reason: null }],
  ["template, opted in, never inbound", base("template", { optedIn: true, lastInboundTimestamp: null }), nowAfter(1), { allowed: true, reason: null }],
  ["template, not opted in", base("template", { optedIn: false, lastInboundTimestamp: null }), nowAfter(1), { allowed: false, reason: "not_opted_in" }],
  ["unknown type", base("image", open()), nowAfter(1), { allowed: false, reason: "unsupported_message_type" }],
  ["missing type", { contact: open() }, nowAfter(1), { allowed: false, reason: "unsupported_message_type" }],
];

let failed = 0;
for (const [name, msg, now, expected] of cases) {
  try {
    assert.deepEqual(decideWhatsApp(msg, now), expected);
    console.log("ok  ", name);
  } catch (e) {
    failed++;
    console.log("FAIL", name, JSON.stringify(decideWhatsApp(msg, now)));
  }
}

// reason codes must be distinct per rule
const codes = ["unsupported_message_type", "not_opted_in", "no_prior_inbound_message", "invalid_inbound_timestamp", "customer_service_window_closed"];
assert.equal(new Set(codes).size, codes.length);

assert.throws(() => decideWhatsApp(base("text", open()), new Date("nope")), TypeError);
console.log("ok   invalid now throws TypeError");

console.log(failed === 0 ? "ALL PASSED" : `${failed} FAILED`);
process.exitCode = failed ? 1 : 0;
